import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import ghidra.program.model.address.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class DumpUnresolvedStringReferences extends GhidraScript{
 static boolean pref(Function f,String p){for(FunctionTag t:f.getTags())if(t.getName().startsWith(p))return true;return false;}static boolean tag(Function f,String n){for(FunctionTag t:f.getTags())if(t.getName().equals(n))return true;return false;}static boolean free(Function f){return !pref(f,"GFZ.V120.PrimaryOwner.")&&!tag(f,"GFZ.V120.FinalNoPrimaryOwner")&&!pref(f,"GFZ.V121.CodeDomain.");}static String e(String s){return s.replace("\\","\\\\").replace("\t","\\t").replace("\n","\\n").replace("\r","\\r");}
 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=1)throw new IllegalArgumentException("out");Listing li=currentProgram.getListing();FunctionIterator fi=currentProgram.getFunctionManager().getFunctions(true);int nf=0,nr=0;try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[0]),StandardCharsets.UTF_8))){w.println("entry\tstrings");while(fi.hasNext()){Function f=fi.next();if(f.isExternal()||!free(f))continue;TreeSet<String> ss=new TreeSet<>();InstructionIterator ii=li.getInstructions(f.getBody(),true);while(ii.hasNext()){Instruction in=ii.next();for(Reference r:in.getReferencesFrom()){if(!r.isMemoryReference())continue;Data d=li.getDataContaining(r.getToAddress());if(d==null)continue;Object v=d.getValue();if(v instanceof String){String s=(String)v;if(!s.isEmpty()&&s.length()<=1000)ss.add(s);}}}if(!ss.isEmpty()){nf++;nr+=ss.size();w.printf("%08X\t%s%n",f.getEntryPoint().getOffset(),e(String.join(" || ",ss)));}}}println("UNRESOLVED_STRING_REFS_PASS functions="+nf+" unique_refs="+nr);}
}
